CREATE TABLE app_user (id UUID PRIMARY KEY, username VARCHAR(120) NOT NULL, nombre VARCHAR(120) NOT NULL, email VARCHAR(254), password_hash VARCHAR(100) NOT NULL, rol VARCHAR(30) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE UNIQUE INDEX ux_user_username_active ON app_user (lower(username)) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX ux_user_email_active ON app_user (lower(email)) WHERE deleted_at IS NULL;
CREATE TABLE marca_moto (id UUID PRIMARY KEY, nombre VARCHAR(100) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE UNIQUE INDEX ux_marca_nombre_active ON marca_moto (lower(nombre)) WHERE deleted_at IS NULL;
CREATE TABLE categoria_catalogo (id UUID PRIMARY KEY, nombre VARCHAR(100) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE UNIQUE INDEX ux_categoria_nombre_active ON categoria_catalogo (lower(nombre)) WHERE deleted_at IS NULL;
CREATE TABLE cliente (id UUID PRIMARY KEY, nombre VARCHAR(160) NOT NULL, documento VARCHAR(50), telefono VARCHAR(80) NOT NULL, email VARCHAR(254), direccion VARCHAR(300), observaciones TEXT, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE UNIQUE INDEX ux_cliente_documento_active ON cliente (lower(documento)) WHERE documento IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX ix_cliente_nombre ON cliente (lower(nombre));
CREATE TABLE motovehiculo (id UUID PRIMARY KEY, cliente_id UUID NOT NULL REFERENCES cliente, marca_id UUID NOT NULL REFERENCES marca_moto, modelo VARCHAR(120) NOT NULL, patente VARCHAR(20) NOT NULL, anio INTEGER, kilometraje INTEGER, color VARCHAR(80), cilindrada VARCHAR(80), observaciones TEXT, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE UNIQUE INDEX ux_moto_patente_active ON motovehiculo (upper(patente)) WHERE deleted_at IS NULL;
CREATE TABLE item_catalogo (id UUID PRIMARY KEY, descripcion VARCHAR(300) NOT NULL, tipo VARCHAR(20) NOT NULL, categoria_id UUID NOT NULL REFERENCES categoria_catalogo, precio_base NUMERIC(14,2) NOT NULL, observaciones TEXT, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE INDEX ix_item_descripcion ON item_catalogo (lower(descripcion));
CREATE TABLE price_history (id UUID PRIMARY KEY, item_id UUID NOT NULL REFERENCES item_catalogo, precio_anterior NUMERIC(14,2), precio_nuevo NUMERIC(14,2) NOT NULL, changed_at TIMESTAMPTZ NOT NULL, changed_by UUID);
CREATE TABLE pedido (id UUID PRIMARY KEY, numero VARCHAR(30) NOT NULL UNIQUE, cliente_id UUID NOT NULL REFERENCES cliente, motovehiculo_id UUID NOT NULL REFERENCES motovehiculo, documento VARCHAR(20) NOT NULL, vencimiento DATE NOT NULL, observaciones TEXT, descuento_global NUMERIC(14,2) NOT NULL DEFAULT 0, iva BOOLEAN NOT NULL DEFAULT FALSE, estado VARCHAR(20) NOT NULL, total NUMERIC(14,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ, deleted_by UUID);
CREATE INDEX ix_pedido_estado_fecha ON pedido (estado, created_at); CREATE INDEX ix_pedido_numero ON pedido(numero);
CREATE TABLE pedido_item (id UUID PRIMARY KEY, pedido_id UUID NOT NULL REFERENCES pedido, item_catalogo_id UUID REFERENCES item_catalogo, descripcion VARCHAR(300) NOT NULL, tipo VARCHAR(20) NOT NULL, cantidad NUMERIC(14,2) NOT NULL, precio_unitario NUMERIC(14,2) NOT NULL, descuento NUMERIC(14,2) NOT NULL, subtotal NUMERIC(14,2) NOT NULL);
CREATE TABLE pedido_foto (id UUID PRIMARY KEY, pedido_id UUID NOT NULL REFERENCES pedido, filename VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, content BYTEA NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE refresh_token (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE auditoria (id UUID PRIMARY KEY, fecha TIMESTAMPTZ NOT NULL, usuario_id UUID REFERENCES app_user, modulo VARCHAR(60) NOT NULL, accion VARCHAR(60) NOT NULL, descripcion TEXT NOT NULL);
